// Illustrative: one fixed-state update per subscription; maxChecks is positive.
body = state.kinematics; inflatedRadius = palletRadius + courierRadius + safetyMargin
check = route => { const waypoint = first(route);
  const acceleration = engine.arrive(body, waypoint, slowRadius, targetRadius, responseTime);
  const preview = integrateVelocityThenPosition(state, acceleration, route);
  const routeGap = minimumSegmentClearance([state.position, ...route]);
  const sweptGap = segmentClearance(state.position, preview.position);
  return { preview, accepted: routeGap >= 0 && sweptGap >= 0 };
}
update$ = defer(() => of(targeter.position(goalX, goalY))).pipe(
  map(goal => ({ goal, route: dropReachedCorners(state.route, targetRadius, cornerSpeed) })),
  concatMap(({ goal, route }) => of(check(route)).pipe(
    expand((candidate, index) => candidate.accepted || index + 1 >= maxChecks ? EMPTY :
      of(check(dropReachedCorners(upperBypass(goal, inflatedRadius + detourPadding),
        targetRadius, cornerSpeed))), 1), // repair feeds back within the check budget
    last() // only the final decision reaches actuation
  )),
  map(({ accepted, preview }) => accepted ? preview : integrateVelocityThenPosition(
    state, engine.matchVelocity(body, zeroVelocity, responseTime), state.route))
) // Streams organise attempts; the helpers still determine geometry and braking safety.
